package io.ratesalgo.backtest.experiment;

import io.ratesalgo.sim.SessionSeeds;
import java.time.LocalDate;
import java.util.List;

/**
 * The data sets no simulator v2 experiment may use (docs/research/SIM_V2_DESIGN.md section 12,
 * "Spent data"), and the seed bases a registered experiment may not use.
 *
 * <p>Spent: the 20 recorded sessions of AUDIT-11 to AUDIT-25 and the five April 2026 "holdout"
 * sessions of AUDIT-26, all under seed base 8,000,000 (seed = base + epoch day of the label
 * date), and every session under bases 5,000,000 and 8,000,000. They were generated by the old
 * simulators and read many times. A simulator v2 seed is base + n with the base a whole million of
 * at least 28,000,000, so a v2 seed can never equal a spent one; the checks here make the refusal
 * explicit and name the reason, so that nobody "replicates" on spent data by passing an old base.
 *
 * <p>Not spent, but not for inference: the acceptance base (28,000,000) belongs to the
 * simulator's tests and the pilot base (29,000,000) measures variance and is then discarded. A
 * registered experiment on either is refused; the pilot mode runs on the pilot base by design.
 */
public final class SpentData {

  /** Seed bases whose every session is spent. */
  public static final List<Long> SPENT_BASES = List.of(5_000_000L, 8_000_000L);

  /** The evaluation period of AUDIT-11 to AUDIT-25 and the holdout dates of AUDIT-26 lie here. */
  public static final LocalDate SPENT_FROM = LocalDate.of(2026, 1, 1);

  /** End of the range that holds every spent label date (the AUDIT-26 holdout is in May 2026). */
  public static final LocalDate SPENT_TO = LocalDate.of(2026, 12, 31);

  private SpentData() {}

  /** Why a registered experiment may not use this seed base, or null when it may. */
  public static String registeredRefusal(final long base) {
    final String spent = spentRefusal(base);
    if (spent != null) {
      return spent;
    }
    if (base == SessionSeeds.ACCEPTANCE) {
      return "seed base " + base + " belongs to the simulator's acceptance tests and supports no claim";
    }
    if (base == SessionSeeds.PILOT) {
      return "seed base " + base + " is the pilot base: it sizes a confirmation set and is then discarded for inference";
    }
    return null;
  }

  /** Why no simulator v2 run of any kind may use this seed base, or null when it may. */
  public static String spentRefusal(final long base) {
    for (final long b : SPENT_BASES) {
      if (base >= b && base < b + SessionSeeds.SPAN) {
        return "seed base " + base + " is spent: every session under " + b
            + " was generated by the old simulators and read by AUDIT-01 to AUDIT-26 (SIM_V2_DESIGN.md section 12)";
      }
    }
    if (base < SessionSeeds.ACCEPTANCE || base % SessionSeeds.SPAN != 0) {
      return "seed base " + base + " is not a simulator v2 base (a whole million of at least "
          + SessionSeeds.ACCEPTANCE + ")";
    }
    return null;
  }

  /**
   * Why a seed may not be used, or null when it may: the seeds of the AUDIT sessions are 8,000,000
   * plus the epoch day of a 2026 date, and the old synthetic days 5,000,000 plus one.
   */
  public static String seedRefusal(final long seed) {
    for (final long b : SPENT_BASES) {
      if (seed >= b + SPENT_FROM.toEpochDay() && seed <= b + SPENT_TO.toEpochDay()) {
        return "seed " + seed + " is a spent session of the old simulators (base " + b + ", label date "
            + LocalDate.ofEpochDay(seed - b) + ")";
      }
      if (seed >= b && seed < b + SessionSeeds.SPAN) {
        return "seed " + seed + " lies under the spent base " + b;
      }
    }
    return null;
  }
}
